448	  auto impl = impl_.lock();
449	  if (!impl) return false;
450	  auto result = impl->get_global_doc_id(id);
451	  if (!result.has_value()) {
452	    return false;
453	  }
454	  uint64_t doc_id = result.value();
455	  if (delete_store_ && delete_store_->is_deleted(doc_id)) {
456	    return true;
457	  }
458	  return false;
