519	Status SegmentImpl::Create(const SegmentOptions &options, uint64_t min_doc_id) {
520	  options_ = options;
521	  filter_ =
522	      std::make_shared<SegmentIndexFilter>(delete_store_, shared_from_this());
523	
524	  // init memory forward block
525	  auto block_id = allocate_block_id();
526	  std::vector<std::string> columns{GLOBAL_DOC_ID, USER_ID};
527	  std::vector<std::string> schema_forward_fields =
528	      collection_schema_->forward_field_names();
529	  columns.insert(columns.end(), schema_forward_fields.begin(),
530	                 schema_forward_fields.end());
531	
532	  segment_meta_->set_writing_forward_block(
533	      {block_id, BlockType::SCALAR, min_doc_id, min_doc_id, 0, columns});
534	  auto vector_fields = collection_schema_->vector_fields();
535	  for (auto &field : vector_fields) {
536	    if (field->index_params()->type() == IndexType::FLAT) {
537	      segment_meta_->add_indexed_vector_field(field->name());
538	    }
539	  }
540	  auto s = load_scalar_index_blocks(true);
541	  CHECK_RETURN_STATUS(s);
542	
543	  s = open_fts_indexers(true);
544	  CHECK_RETURN_STATUS(s);
545	
546	  doc_id_allocator_.store(min_doc_id);
547	
548	  return Status::OK();
549	}
550	
551	Status SegmentImpl::close() {
552	  flush();
553	  if (invert_indexers_) {
554	    invert_indexers_.reset();
555	  }
556	  close_fts_indexers();
557	  for (const auto &[name, indexers] : vector_indexers_) {
558	    for (auto indexer : indexers) {
559	      indexer->Close();
560	    }
561	  }

